 "content": "def transform(grid):
    """Replace every cell in a solid monochrome rectangle of at least 5x5 with 4."""
    h, w = len(grid), len(grid[0])
    marked = [[False] * w for _ in range(h)]
    min_side = 5
    for top in range(h):
        for left in range(w):
            color = grid[top][left]
            width = w - left
            for bottom in range(top, h):
                # A 5-cell seed is necessary; if absent, no rectangle from this
                # top-left can qualify.
                run = 0
                while left + run < w and grid[bottom][left + run] == color:
                    run += 1
                width = min(width, run)
                height = bottom - top + 1
                if height >= min_side and width >= min_side:
                    for r in range(top, bottom + 1):
                        for c in range(left, left + width):
                            marked[r][c] = True
    return [[4 if marked[r][c] else grid[r][c] for c in range(w)] for r in range(h)]

if __name__ == "__main__":
    pass
